const express = require("express");
const { findCommentsByArticleSlug } = require("./comments");

const RESPONSE_ERRORS = {
  notFound: { status: 404, code: "not_found" },
  serverError: { status: 500, code: "server_error" },
};

function sendError(res, { status, code }) {
  return res.status(status).json({ error: code });
}

async function getArticleComments(req, res) {
  try {
    const comments = await findCommentsByArticleSlug(req.params.slug);
    if (!comments) {
      return sendError(res, RESPONSE_ERRORS.notFound);
    }

    res.json({ comments });
  } catch (error) {
    console.error(error);
    sendError(res, RESPONSE_ERRORS.serverError);
  }
}

function createCommentRouter() {
  const router = express.Router();

  router.get("/articles/:slug/comments", getArticleComments);

  return router;
}

module.exports = { createCommentRouter };

